sys_ui_action.script:
// 1. CLIENT-SIDE: This runs in the browser first to catch the click
function onClickApproveFulfill() {
    // Show the confirmation pop-up box
    var confirmApprove = confirm("Are you sure you want to approve and fulfill this request?");

    // If the user clicks 'Cancel', abort immediately
    if (!confirmApprove) {
        return false;
    }

    // If they click 'OK', safely submit the form to run the server block
    gsftSubmit(null, g_form.getFormElement(), 'approve_and_fulfill_action');
}

// 2. SERVER-SIDE: This block is triggered ONLY after clicking 'OK' on the pop-up
if (typeof window == 'undefined') {
    runFulfillmentCode();
}

function runFulfillmentCode() {
    var utils = new OnboardingUtils();

    // Validate using your custom Script Include
    if (utils.validateRequest(current)) {

        // Set standard RITM fulfillment values
        current.state = 3;             // OOTB RITM State 3 = Closed Complete
        current.stage = 'fulfillment';  // Update workflow stage

        // Safely handle assigning the closer
        if (current.isValidField('assigned_to')) {
            current.assigned_to = gs.getUserID();
        }

        // If a custom resolution field exists, track who resolved it
        if (current.isValidField('u_resolved_by')) {
            current.u_resolved_by = gs.getUserID();
        }

        utils.logAction(current, 'Request Approved and Fulfilled');
        current.update();

        // Keep the user on the current record page instead of routing to a blank form
        action.setRedirectURL(current);
        gs.addInfoMessage(gs.getMessage('Requested Item {0} has been successfully closed and fulfilled.', current.number));

    } else {
        // Validation failed - show error banner and stay on page
        gs.addErrorMessage('Fulfillment failed: Please ensure the required operational fields (Assignment Group, Category, and Due Date) are populated.');
        action.setRedirectURL(current);
    }
}
